// Copied from go-fast-html internal/charset at commit be5c679 (dbcs.go,
// and dbcsAt, userDefined and isLead from charset.go), which copied
// dbcs.go from go-fast-rtf internal/codepage at commit b756076; the tables
// are generated by gen/gen_dbcs.py, copied from the same place. See NOTICE.

package charset

import (
	"embed"
	"strconv"
	"strings"
	"sync"
	"unicode/utf8"
)

// The double-byte code pages 932 (Shift_JIS), 936 (GBK), 949 (EUC-KR,
// Unified Hangul Code) and 950 (Big5) are read from the tables in
// tables/cp932.txt ... cp950.txt, written by gen/gen_dbcs.py (see its
// header and NOTICE). Each is parsed the first time a message uses it,
// into an array for each lead byte, indexed by the trail byte; a lead
// byte with no characters has no array. A code page whose table is not
// in tables/ is not decoded: its labels are unknown, as before.

//go:embed tables
var dbcsFS embed.FS

// trailFirst is the lowest trail byte any of the four code pages uses.
const trailFirst = 0x40

type dbcs struct {
	single [128]uint16                    // bytes 0x80-0xFF that are characters alone
	lead   [128]*[256 - trailFirst]uint16 // by lead byte - 0x80, then trail - trailFirst
}

type lazyTable struct {
	once sync.Once
	file string
	t    *dbcs
}

var dbcsTables = map[int]*lazyTable{
	932: {file: "tables/cp932.txt"},
	936: {file: "tables/cp936.txt"},
	949: {file: "tables/cp949.txt"},
	950: {file: "tables/cp950.txt"},
}

// dbcsLabels gives the code page of each label of a double-byte set, as
// the WHATWG Encoding Standard lists them, with the names Windows and mail
// programs use. GB2312 is decoded as GBK, its superset, as the Encoding
// Standard does; EUC-KR as code page 949, its superset.
var dbcsLabels = map[string]int{
	"shift_jis": 932, "shift-jis": 932, "sjis": 932, "ms932": 932, "windows-31j": 932, "x-sjis": 932,
	"csshiftjis": 932, "ms_kanji": 932, "cp932": 932,

	"gbk": 936, "gb2312": 936, "chinese": 936, "csgb2312": 936, "csiso58gb231280": 936, "gb_2312": 936,
	"gb_2312-80": 936, "iso-ir-58": 936, "x-gbk": 936, "cp936": 936,

	"euc-kr": 949, "ks_c_5601-1987": 949, "ks_c_5601-1989": 949, "ksc5601": 949, "ksc_5601": 949,
	"windows-949": 949, "cseuckr": 949, "csksc56011987": 949, "iso-ir-149": 949, "korean": 949, "cp949": 949,

	"big5": 950, "big5-hkscs": 950, "cn-big5": 950, "csbig5": 950, "x-x-big5": 950, "cp950": 950,
}

// dbcsTable returns the parsed table of code page cp, or nil.
func dbcsTable(cp int) *dbcs {
	l, ok := dbcsTables[cp]
	if !ok {
		return nil
	}
	return l.get()
}

// parseDBCS reads lines of "<bytes in hex> <code point in hex>". A line
// it cannot read is left out; the tables are this package's own.
func parseDBCS(text string) *dbcs {
	t := &dbcs{}
	for line := range strings.SplitSeq(text, "\n") {
		if line == "" || line[0] == '#' {
			continue
		}
		key, val, ok := strings.Cut(line, " ")
		if !ok {
			continue
		}
		k, err1 := strconv.ParseUint(key, 16, 16)
		v, err2 := strconv.ParseUint(strings.TrimSpace(val), 16, 32)
		if err1 != nil || err2 != nil || v == 0 || v > 0xFFFF {
			continue
		}
		switch len(key) {
		case 2:
			if k >= 0x80 {
				t.single[k-0x80] = uint16(v)
			}
		case 4:
			lead, trail := k>>8, k&0xFF
			if lead < 0x80 || trail < trailFirst {
				continue
			}
			arr := t.lead[lead-0x80]
			if arr == nil {
				arr = new([256 - trailFirst]uint16)
				t.lead[lead-0x80] = arr
			}
			arr[trail-trailFirst] = uint16(v)
		}
	}
	return t
}

// pair returns the character of a lead and trail byte, or 0.
func (t *dbcs) pair(lead, trail byte) rune {
	if lead < 0x80 || trail < trailFirst {
		return 0
	}
	if arr := t.lead[lead-0x80]; arr != nil {
		return rune(arr[trail-trailFirst])
	}
	return 0
}

// decodeDBCS decodes b in double-byte code page cp, whose table is t.
func decodeDBCS(t *dbcs, cp int, b []byte) (string, Result) {
	res := Result{Known: true}
	var sb strings.Builder
	sb.Grow(len(b) + len(b)/2)
	for s := 0; s < len(b); {
		if b[s] < 0x80 {
			sb.WriteByte(b[s])
			s++
			continue
		}
		r, n, bad := dbcsAt(t, b, s, cp)
		if bad {
			res.Replaced = true
		}
		sb.WriteRune(r)
		s += n
	}
	return sb.String(), res
}

// dbcsAt decodes a character of double-byte code page cp at src[s:],
// whose first byte is not ASCII. A lead byte and a trail byte that do not
// make a character are U+FFFD; if the trail byte is ASCII it is read
// again as a character of its own, as the Encoding standard's decoders
// do. A lead byte at the end of src is U+FFFD.
func dbcsAt(t *dbcs, src []byte, s int, cp int) (rune, int, bool) {
	b := src[s]
	if !isLead(cp, b) {
		if r := t.single[b-0x80]; r != 0 {
			return rune(r), 1, false
		}
		if cp == 932 && b == 0x80 {
			// The Encoding standard's Shift_JIS decoder reads 0x80 as
			// U+0080.
			return 0x80, 1, false
		}
		return utf8.RuneError, 1, true
	}
	if s+1 >= len(src) {
		return utf8.RuneError, 1, true
	}
	trail := src[s+1]
	if r := t.pair(b, trail); r != 0 {
		return r, 2, false
	}
	if r := userDefined(cp, b, trail); r != 0 {
		return r, 2, false
	}
	if trail < 0x80 {
		return utf8.RuneError, 1, true
	}
	return utf8.RuneError, 2, true
}

// userDefined returns the Private Use Area character the Encoding
// standard gives a lead and trail byte in a user-defined area that the
// code page tables leave out, or 0.
func userDefined(cp int, lead, trail byte) rune {
	switch cp {
	case 932:
		// Shift_JIS pointers 8836 to 10715: lead bytes 0xF0 to 0xF9,
		// trail bytes 0x40 to 0x7E and 0x80 to 0xFC, to U+E000 onwards.
		if lead < 0xF0 || lead > 0xF9 || trail < 0x40 || trail == 0x7F || trail > 0xFC {
			return 0
		}
		off := 0x40
		if trail > 0x7F {
			off = 0x41
		}
		return 0xE000 + rune(lead-0xF0)*188 + rune(int(trail)-off)
	case 936:
		// GBK's user-defined areas, as GB 18030 and the Encoding
		// standard's index-gb18030 map them.
		switch {
		case lead >= 0xAA && lead <= 0xAF && trail >= 0xA1 && trail <= 0xFE:
			return 0xE000 + rune(lead-0xAA)*94 + rune(trail-0xA1)
		case lead >= 0xF8 && lead <= 0xFE && trail >= 0xA1 && trail <= 0xFE:
			return 0xE234 + rune(lead-0xF8)*94 + rune(trail-0xA1)
		case lead >= 0xA1 && lead <= 0xA7 && trail >= 0x40 && trail <= 0xA0 && trail != 0x7F:
			off := rune(trail - 0x40)
			if trail > 0x7F {
				off--
			}
			return 0xE4C6 + rune(lead-0xA1)*96 + off
		}
	}
	return 0
}

// isLead reports whether b is a lead byte of double-byte code page cp.
func isLead(cp int, b byte) bool {
	switch cp {
	case 932:
		return b >= 0x81 && b <= 0x9F || b >= 0xE0 && b <= 0xFC
	case 936, 949, 950:
		return b >= 0x81 && b <= 0xFE
	}
	return false
}
